package com.trampolim.api.company;
import java.util.*;
import java.time.*;
import com.trampolim.api.future.FutureModel;
import static com.trampolim.api.future.FutureModel.*;
import com.trampolim.api.radar.*;
import static com.trampolim.api.radar.RadarModel.*;
import org.springframework.beans.factory.annotation.Qualifier;
import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.http.HttpStatus;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
@RestController
@ConditionalOnProperty(name="trampolim.datasource.empresas.enabled",havingValue="true")
public class CompanyFutureController {
 private final JdbcTemplate jdbc;private final RadarBridge bridge;
 public CompanyFutureController(@Qualifier("empresasJdbcTemplate")JdbcTemplate jdbc,RadarBridge bridge){this.jdbc=jdbc;this.bridge=bridge;}
 private long member(String email,boolean edit){var rows=jdbc.queryForList("SELECT m.company_id,m.role FROM company_members m JOIN company_users u ON u.id=m.user_id WHERE LOWER(u.email)=LOWER(?) AND u.account_status='ACTIVE' AND u.email_verified=TRUE",email);if(rows.isEmpty())throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Entre com uma conta empresarial verificada e vinculada.");var row=rows.get(0);if(edit&&!Set.of("OWNER","ADMIN","RECRUITER").contains(row.get("role")))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Seu papel permite apenas consultar as previsões.");return ((Number)row.get("company_id")).longValue();}
 private void own(String email,long id,boolean edit){long company=member(email,edit);if(!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM company_future_demands WHERE id=? AND company_id=?)",Boolean.class,id,company)))throw new ResponseStatusException(HttpStatus.NOT_FOUND,"Previsão não disponível para sua empresa.");}
 private void audit(String email,long company,String event){jdbc.update("INSERT INTO company_audit_events(company_id,actor_user_id,event_type) SELECT ?,id,? FROM company_users WHERE LOWER(email)=LOWER(?)",company,event,email);}
 private String select(){return "SELECT d.*,c.trade_name FROM company_future_demands d JOIN companies c ON c.id=d.company_id";}
 private List<Demand> query(String suffix,Object... args){return jdbc.query(select()+suffix,(rs,n)->new Demand(rs.getLong("id"),rs.getString("occupation"),rs.getString("description"),rs.getString("area"),rs.getInt("estimated_hires"),rs.getString("education_description"),rs.getString("experience_description"),rs.getString("region"),rs.getString("modality"),rs.getDate("hiring_start").toLocalDate().toString(),rs.getDate("hiring_end").toLocalDate().toString(),rs.getString("status"),rs.getInt("revision"),rs.getString("trade_name"),bridge.convert(bridge.read(rs.getObject("requirements")),Requirements.class),rs.getTimestamp("updated_at").toInstant().toString()),args);}
 private String available(){return " d.status='PUBLISHED' AND c.verification_status='APPROVED' AND d.hiring_end>=(CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo')::date";}
 @GetMapping("/api/company/future-demands")public Map<String,Object> list(@AuthenticationPrincipal String email,@RequestParam(defaultValue="9223372036854775807")long before,@RequestParam(defaultValue="20")int limit,@RequestParam(defaultValue="")String status){long company=member(email,false);page(before,limit);if(!status.isEmpty()&&!Set.of("DRAFT","PUBLISHED","SUSPENDED","ARCHIVED").contains(status))bad("Situação inválida.");var rows=query(" WHERE d.company_id=? AND d.id<? AND (?='' OR d.status=?) ORDER BY d.id DESC LIMIT ?",company,before,status,status,limit+1);var result=new LinkedHashMap<String,Object>();result.put("items",rows.stream().limit(limit).toList());result.put("nextCursor",rows.size()>limit?rows.get(limit-1).id():null);return result;}
 @GetMapping("/api/company/future-demands/{id}")public Demand detail(@AuthenticationPrincipal String email,@PathVariable long id){own(email,id,false);return query(" WHERE d.id=?",id).get(0);}
 @PostMapping("/api/company/future-demands")@Transactional("empresasTransactionManager")public Demand create(@AuthenticationPrincipal String email,@RequestBody Input body){var input=FutureModel.validate(body);long company=member(email,true);if(!input.status().equals("DRAFT"))bad("Crie o rascunho, revise as competências e só então publique a previsão.");jdbc.queryForObject("SELECT id FROM companies WHERE id=? FOR UPDATE",Long.class,company);if(jdbc.queryForObject("SELECT count(*) FROM company_future_demands WHERE company_id=? AND status<>'ARCHIVED'",Integer.class,company)>=500)throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,"Arquive previsões antigas antes de criar outras.");long id=jdbc.queryForObject("INSERT INTO company_future_demands(company_id,occupation,description,area,estimated_hires,education_description,experience_description,region,modality,hiring_start,hiring_end,status) VALUES (?,?,?,?,?,?,?,?,?,?,?,?) RETURNING id",Long.class,company,input.occupation(),input.description(),input.area(),input.estimatedHires(),input.educationDescription(),input.experienceDescription(),input.region(),input.modality(),LocalDate.parse(input.hiringStart()),LocalDate.parse(input.hiringEnd()),input.status());audit(email,company,"FUTURE_DEMAND_CREATED");return detail(email,id);}
 @PutMapping("/api/company/future-demands/{id}")@Transactional("empresasTransactionManager")public Demand update(@AuthenticationPrincipal String email,@PathVariable long id,@RequestBody Input body){own(email,id,true);var input=FutureModel.validate(body);jdbc.queryForObject("SELECT id FROM company_future_demands WHERE id=? FOR UPDATE",Long.class,id);var previous=detail(email,id);if(input.status().equals("PUBLISHED")&&!Boolean.TRUE.equals(jdbc.queryForObject("SELECT verification_status='APPROVED' FROM companies WHERE id=?",Boolean.class,member(email,true))))bad("A empresa precisa estar aprovada antes de publicar previsões.");if(input.status().equals("PUBLISHED")&&previous.requirements().skills().isEmpty())bad("Cadastre ao menos uma competência antes de publicar.");if(previous.status().equals("ARCHIVED")&&!input.status().equals("ARCHIVED")&&jdbc.queryForObject("SELECT count(*) FROM company_future_demands WHERE company_id=? AND status<>'ARCHIVED'",Integer.class,member(email,true))>=500)bad("Limite de previsões ativas atingido.");int changed=jdbc.update("UPDATE company_future_demands SET occupation=?,description=?,area=?,estimated_hires=?,education_description=?,experience_description=?,region=?,modality=?,hiring_start=?,hiring_end=?,status=?,revision=revision+1,updated_at=CURRENT_TIMESTAMP WHERE id=? AND revision=?",input.occupation(),input.description(),input.area(),input.estimatedHires(),input.educationDescription(),input.experienceDescription(),input.region(),input.modality(),LocalDate.parse(input.hiringStart()),LocalDate.parse(input.hiringEnd()),input.status(),id,input.revision());if(changed==0)throw new ResponseStatusException(HttpStatus.CONFLICT,"A previsão mudou. Reabra os dados antes de salvar.");audit(email,member(email,true),"FUTURE_DEMAND_UPDATED");return detail(email,id);}
 @GetMapping("/api/company/future-demands/{id}/requirements")public Requirements requirements(@AuthenticationPrincipal String email,@PathVariable long id){return detail(email,id).requirements();}
 @PutMapping("/api/company/future-demands/{id}/requirements")@ResponseStatus(HttpStatus.NO_CONTENT)@Transactional("empresasTransactionManager")public void requirements(@AuthenticationPrincipal String email,@PathVariable long id,@RequestBody Requirements body){own(email,id,true);var r=RadarModel.validate(body);bridge.validateSkills(r.skills().stream().map(Need::skillCode).toList());jdbc.queryForObject("SELECT id FROM company_future_demands WHERE id=? FOR UPDATE",Long.class,id);var previous=detail(email,id);if(r.revision()!=previous.requirements().revision())throw new ResponseStatusException(HttpStatus.CONFLICT,"Os critérios mudaram. Atualize a previsão.");if(previous.status().equals("PUBLISHED")&&r.skills().isEmpty())bad("Suspenda a previsão antes de remover todos os critérios.");var next=new Requirements(r.revision()+1,r.skills(),r.experienceMonths(),r.educationLevel(),r.experienceEliminatory(),r.educationEliminatory(),r.city(),r.modality(),r.area());jdbc.update("UPDATE company_future_demands SET requirements=?::jsonb,revision=revision+1,updated_at=CURRENT_TIMESTAMP WHERE id=?",bridge.encode(next),id);audit(email,member(email,true),"FUTURE_CRITERIA_UPDATED");}
 @GetMapping("/api/company/future-demands/{id}/preparation")public Map<String,Object> preparation(@AuthenticationPrincipal String email,@PathVariable long id){var demand=detail(email,id);return bridge.convert(bridge.post("/integrations/future/summary",new SummaryRequest(id,demand.requirements().revision())),Map.class);}
 @GetMapping("/api/company/future-indicators")public Map<String,Object> indicators(@AuthenticationPrincipal String email){long company=member(email,false);var result=new LinkedHashMap<String,Object>(jdbc.queryForMap("SELECT count(*) AS demands,count(DISTINCT occupation) AS occupations,COALESCE(sum(estimated_hires) FILTER(WHERE status='PUBLISHED' AND hiring_end>=(CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo')::date),0) AS estimated_hires,count(*) FILTER(WHERE status='PUBLISHED' AND hiring_end>=(CURRENT_TIMESTAMP AT TIME ZONE 'America/Sao_Paulo')::date) AS published_forecasts FROM company_future_demands WHERE company_id=?",company));result.put("skills",jdbc.queryForList("SELECT x->>'skillCode' AS skill_code,count(*) AS demand_count FROM company_future_demands d CROSS JOIN LATERAL jsonb_array_elements(d.requirements->'skills') x WHERE company_id=? AND status<>'ARCHIVED' GROUP BY x->>'skillCode' ORDER BY count(*) DESC,skill_code LIMIT 40",company));result.put("linkedVacancies",jdbc.queryForObject("SELECT count(DISTINCT l.listing_id) FROM company_future_job_links l JOIN company_future_demands d ON d.id=l.demand_id WHERE d.company_id=?",Integer.class,company));result.put("currentlyOpenLinkedVacancies",jdbc.queryForObject("SELECT count(DISTINCT l.id) FROM company_future_job_links f JOIN company_future_demands d ON d.id=f.demand_id JOIN company_listings l ON l.id=f.listing_id JOIN companies c ON c.id=l.company_id WHERE d.company_id=? AND "+CompanyRadarController.PUBLIC_JOB_CONDITION,Integer.class,company));result.put("demandsWithLinkedVacancies",jdbc.queryForObject("SELECT count(DISTINCT f.demand_id) FROM company_future_job_links f JOIN company_future_demands d ON d.id=f.demand_id WHERE d.company_id=?",Integer.class,company));result.put("confirmedHires",null);result.put("hireNotice","A plataforma não registra confirmação de vínculo empregatício. Estimativas e candidaturas aceitas não são contratações confirmadas.");return result;}
 @GetMapping("/api/company/future-demands/{id}/vacancies")public List<Map<String,Object>> links(@AuthenticationPrincipal String email,@PathVariable long id){own(email,id,false);return jdbc.queryForList("SELECT f.id,f.listing_id,l.title,l.publication_status,f.linked_at FROM company_future_job_links f JOIN company_listings l ON l.id=f.listing_id WHERE f.demand_id=? ORDER BY f.id DESC LIMIT 100",id);}
 @PostMapping("/api/company/future-demands/{id}/vacancies")@Transactional("empresasTransactionManager")public Map<String,Object> link(@AuthenticationPrincipal String email,@PathVariable long id,@RequestBody VacancyLink body){own(email,id,true);if(body==null||body.listingId()<1)bad("Selecione uma vaga real publicada da sua empresa.");jdbc.queryForObject("SELECT id FROM company_future_demands WHERE id=? FOR UPDATE",Long.class,id);var d=detail(email,id);if(!d.status().equals("PUBLISHED"))bad("A previsão deve estar publicada para vincular uma vaga e autorizar o aviso.");var rows=jdbc.queryForList("SELECT l.id FROM company_listings l JOIN companies c ON c.id=l.company_id WHERE l.id=? AND l.company_id=? AND "+CompanyRadarController.PUBLIC_JOB_CONDITION+" FOR UPDATE OF l",body.listingId(),member(email,true));if(rows.isEmpty())bad("A vaga deve estar publicada, disponível e aprovada, com pagamento confirmado quando exigido.");if(jdbc.queryForObject("SELECT count(*) FROM company_future_job_links WHERE demand_id=?",Integer.class,id)>=100&&!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM company_future_job_links WHERE demand_id=? AND listing_id=?)",Boolean.class,id,body.listingId())))throw new ResponseStatusException(HttpStatus.TOO_MANY_REQUESTS,"Limite de cem vagas vinculadas por previsão atingido.");jdbc.queryForObject("SELECT pg_advisory_xact_lock(hashtext('future-job-events'))",(rs,n)->0);jdbc.update("INSERT INTO company_future_job_links(demand_id,listing_id,linked_at) VALUES (?,?,clock_timestamp()) ON CONFLICT DO NOTHING",id,body.listingId());audit(email,member(email,true),"FUTURE_REAL_JOB_LINKED");return Map.of("linked",true,"notice","Vaga real vinculada. Interessados autorizados serão avisados pelo processamento interno; nenhuma previsão virou vaga automaticamente.");}
 @GetMapping("/api/public/companies/future-demands")public Map<String,Object> publicList(@RequestParam(defaultValue="9223372036854775807")long before,@RequestParam(defaultValue="20")int limit,@RequestParam(defaultValue="")String q,@RequestParam(defaultValue="")String region,@RequestParam(defaultValue="")String modality){page(before,limit);text(q,120);text(region,180);text(modality,40);var rows=query(" WHERE "+available()+" AND d.id<? AND (?='' OR d.occupation ILIKE ? OR d.area ILIKE ?) AND (?='' OR d.region ILIKE ?) AND (?='' OR d.modality=?) ORDER BY d.id DESC LIMIT ?",before,q,"%"+q+"%","%"+q+"%",region,"%"+region+"%",modality,modality,limit+1);var result=new LinkedHashMap<String,Object>();result.put("items",rows.stream().limit(limit).toList());result.put("nextCursor",rows.size()>limit?rows.get(limit-1).id():null);return result;}
 @GetMapping("/api/public/companies/future-demands/{id}")public Demand publicDetail(@PathVariable long id){return query(" WHERE "+available()+" AND d.id=?",id).stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Previsão suspensa, arquivada, vencida ou não disponível."));}
 @GetMapping("/api/public/companies/future-job-events")public Map<String,Object> events(@RequestParam(defaultValue="0")long after,@RequestParam(defaultValue="100")int limit){if(after<0||limit<1||limit>100)bad("Consulta inválida.");var scanned=jdbc.queryForList("SELECT id FROM company_future_job_links WHERE id>? ORDER BY id LIMIT ?",after,limit);long end=scanned.isEmpty()?after:((Number)scanned.get(scanned.size()-1).get("id")).longValue();var rows=jdbc.queryForList("SELECT f.id AS event_id,f.demand_id,f.listing_id,l.title,f.linked_at AS published_at FROM company_future_job_links f JOIN company_listings l ON l.id=f.listing_id JOIN companies c ON c.id=l.company_id WHERE f.id>? AND f.id<=? AND "+CompanyRadarController.PUBLIC_JOB_CONDITION+" ORDER BY f.id",after,end);return Map.of("items",rows,"nextCursor",end);}
 @GetMapping("/api/public/companies/future-vacancies/{id}")public Map<String,Object> publicVacancy(@PathVariable long id){return jdbc.queryForList("SELECT l.id,l.title,l.description,l.requirements,l.area,l.location,l.modality,c.public_slug AS company_slug,c.trade_name AS company_name FROM company_listings l JOIN companies c ON c.id=l.company_id WHERE l.id=? AND "+CompanyRadarController.PUBLIC_JOB_CONDITION,id).stream().findFirst().orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Esta vaga não está mais disponível."));}
 private void page(long before,int limit){if(before<1||limit<1||limit>50)bad("Use páginas de até 50 previsões.");}
}
